class Nodo {
  constructor(valor) { this.valor = valor; this.sig = null; }
}

class ListaEnlazada {
  constructor() { this.cabeza = null; this.largo = 0; }

  // Agregar al frente: siempre los mismos pasos, sin importar el largo
  agregarAlFrente(valor) {
    const nodo = new Nodo(valor);
    nodo.sig = this.cabeza;
    this.cabeza = nodo;
    this.largo++;
    return nodo;
  }

  // Agregar al final sin tener guardado el último: hay que caminar toda la lista
  agregarAlFinal(valor) {
    const nodo = new Nodo(valor);
    this.largo++;
    if (this.cabeza === null) { this.cabeza = nodo; return nodo; }
    let p = this.cabeza;
    while (p.sig !== null) p = p.sig;
    p.sig = nodo;
    return nodo;
  }

  // Insertar después de un nodo que ya tenés en la mano: tres asignaciones, sin recorrer nada
  insertarDespues(nodo, valor) {
    const nuevo = new Nodo(valor);
    nuevo.sig = nodo.sig;
    nodo.sig = nuevo;
    this.largo++;
    return nuevo;
  }

  // Borrar el nodo que viene después de uno que ya tenés
  borrarDespues(nodo) {
    const borrado = nodo.sig;
    if (borrado === null) return undefined;
    nodo.sig = borrado.sig;
    this.largo--;
    return borrado.valor;
  }

  // Buscar por valor: hay que mirar de a uno
  buscar(valor) {
    for (let p = this.cabeza; p !== null; p = p.sig) if (p.valor === valor) return p;
    return null;
  }

  // El elemento número i: no hay cuenta directa, hay que dar i pasos
  obtener(i) {
    let p = this.cabeza;
    while (i-- > 0 && p !== null) p = p.sig;
    return p === null ? undefined : p.valor;
  }

  aArray() { const r = []; for (let p = this.cabeza; p !== null; p = p.sig) r.push(p.valor); return r; }
}

