// Recorrer N enteros guardados en un array y en una lista enlazada (ordenada en memoria o dispersa).
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Nodo { int valor; struct Nodo *sig; } Nodo;   // 16 bytes en esta máquina

static double ahora(void) {
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec * 1e3 + t.tv_nsec / 1e6;          // milisegundos
}

int main(int argc, char **argv) {
    long N = argc > 1 ? atol(argv[1]) : 10000000;
    int *arr = malloc(N * sizeof(int));
    Nodo *nodos = malloc(N * sizeof(Nodo));           // un solo bloque: los nodos quedan uno al lado del otro
    long *orden = malloc(N * sizeof(long));
    for (long i = 0; i < N; i++) { arr[i] = i % 7; nodos[i].valor = i % 7; orden[i] = i; }

    double t_arr[3], t_arr16[3], t_ord[3], t_dis[3];
    long s1 = 0, s2 = 0, s3 = 0, s4 = 0;

    // Lista ordenada: cada nodo apunta al que tiene al lado en memoria
    for (long i = 0; i < N - 1; i++) nodos[i].sig = &nodos[i + 1];
    nodos[N - 1].sig = NULL;
    for (int rep = 0; rep < 3; rep++) {
        double t0 = ahora();
        s1 = 0; for (long i = 0; i < N; i++) s1 += arr[i];
        double t1 = ahora();
        s4 = 0; for (long i = 0; i < N; i++) s4 += nodos[i].valor;      // array de estructuras de 16 bytes
        double t2 = ahora();
        s2 = 0; for (Nodo *p = &nodos[0]; p; p = p->sig) s2 += p->valor;
        double t3 = ahora();
        t_arr[rep] = t1 - t0; t_arr16[rep] = t2 - t1; t_ord[rep] = t3 - t2;
    }

    // Lista dispersa: los mismos nodos, enlazados en un orden mezclado (semilla fija)
    srand(12345);
    for (long i = N - 1; i > 0; i--) {
        long j = ((long)rand() * 32768 + rand()) % (i + 1);
        long t = orden[i]; orden[i] = orden[j]; orden[j] = t;
    }
    for (long i = 0; i < N - 1; i++) nodos[orden[i]].sig = &nodos[orden[i + 1]];
    nodos[orden[N - 1]].sig = NULL;
    for (int rep = 0; rep < 3; rep++) {
        double t0 = ahora();
        s3 = 0; for (Nodo *p = &nodos[orden[0]]; p; p = p->sig) s3 += p->valor;
        t_dis[rep] = ahora() - t0;
    }

    printf("N = %ld (sumas: %ld %ld %ld %ld)\n", N, s1, s4, s2, s3);
    for (int rep = 0; rep < 3; rep++)
        printf("  array de int: %7.1f ms | array de 16 bytes: %7.1f ms | lista ordenada: %8.1f ms | lista dispersa: %8.1f ms\n",
               t_arr[rep], t_arr16[rep], t_ord[rep], t_dis[rep]);
    printf("tamaños: int = %zu bytes, nodo = %zu bytes\n", sizeof(int), sizeof(Nodo));
    free(arr); free(nodos); free(orden);
    return 0;
}

