// Lista doble: cada nodo conoce al anterior y al siguiente
class NodoDoble {
  constructor(clave, valor) { this.clave = clave; this.valor = valor; this.ant = null; this.sig = null; }
}

class ListaDoble {
  constructor() {
    // Dos nodos «guardia» (sin dato) en los extremos: así nunca hay que tratar «la lista está vacía» como caso aparte
    this.inicio = new NodoDoble(null, null);
    this.fin = new NodoDoble(null, null);
    this.inicio.sig = this.fin;
    this.fin.ant = this.inicio;
  }
  agregarAlFrente(nodo) {
    nodo.ant = this.inicio;
    nodo.sig = this.inicio.sig;
    this.inicio.sig.ant = nodo;
    this.inicio.sig = nodo;
  }
  // Quitar un nodo que ya tenés: cuatro asignaciones, sin buscarlo ni caminar
  quitar(nodo) {
    nodo.ant.sig = nodo.sig;
    nodo.sig.ant = nodo.ant;
    nodo.ant = nodo.sig = null;
  }
  ultimo() { return this.fin.ant === this.inicio ? null : this.fin.ant; }
  claves() { const r = []; for (let p = this.inicio.sig; p !== this.fin; p = p.sig) r.push(p.clave); return r; }
}

// Caché LRU: guarda hasta «capacidad» elementos y, al llenarse, descarta el que hace más tiempo que nadie usa.
// Un diccionario (Map) encuentra el nodo por clave; la lista doble ordena del más reciente al más viejo.
class CacheLRU {
  constructor(capacidad) {
    this.capacidad = capacidad;
    this.indice = new Map();
    this.lista = new ListaDoble();
    this.aciertos = 0;
    this.fallos = 0;
  }
  obtener(clave) {
    const nodo = this.indice.get(clave);
    if (!nodo) { this.fallos++; return undefined; }
    this.aciertos++;
    this.lista.quitar(nodo);              // sin buscar: ya tenemos el nodo
    this.lista.agregarAlFrente(nodo);     // pasa a ser el más reciente
    return nodo.valor;
  }
  poner(clave, valor) {
    let nodo = this.indice.get(clave);
    if (nodo) { nodo.valor = valor; this.lista.quitar(nodo); this.lista.agregarAlFrente(nodo); return; }
    if (this.indice.size >= this.capacidad) {
      const viejo = this.lista.ultimo();  // el que hace más tiempo que nadie toca
      this.lista.quitar(viejo);
      this.indice.delete(viejo.clave);
    }
    nodo = new NodoDoble(clave, valor);
    this.indice.set(clave, nodo);
    this.lista.agregarAlFrente(nodo);
  }
}

