// La cola de ayer, ahora con nodos: encolar y desencolar cuestan siempre lo mismo, sin mover nada
class Nodo { constructor(valor) { this.valor = valor; this.sig = null; } }

class ColaEnlazada {
  constructor() { this.frente = null; this.fondo = null; this.tamano = 0; }
  encolar(valor) {
    const nodo = new Nodo(valor);
    if (this.fondo === null) this.frente = nodo; else this.fondo.sig = nodo;
    this.fondo = nodo;
    this.tamano++;
  }
  desencolar() {
    if (this.frente === null) throw new Error("cola vacía");
    const nodo = this.frente;
    this.frente = nodo.sig;
    if (this.frente === null) this.fondo = null;   // quedó vacía
    this.tamano--;
    return nodo.valor;
  }
}

function conShift(N) {
  const q = [];
  for (let i = 0; i < N; i++) q.push(i);
  const t0 = performance.now(); let s = 0;
  while (q.length) s += q.shift();
  return performance.now() - t0;
}
function conNodos(N) {
  const q = new ColaEnlazada();
  for (let i = 0; i < N; i++) q.encolar(i);
  const t0 = performance.now(); let s = 0;
  while (q.tamano) s += q.desencolar();
  return performance.now() - t0;
}

