function invertir(cabeza) {
  let anterior = null, actual = cabeza;
  while (actual !== null) {
    const siguiente = actual.sig;   // guardamos el camino antes de cortarlo
    actual.sig = anterior;          // damos vuelta la flecha de este nodo
    anterior = actual;              // avanzamos las dos marcas
    actual = siguiente;
  }
  return anterior;                  // el último nodo visitado es la nueva cabeza
}

